        "sections": [
          {
            "title": "Combat Skills",
            "entries": [
              {
                "name": "Seek and Hunt",
                "type": "Combat Skill",
                "desc": "BASIC ATTACK:\nAn attack with up to 5 sequences that deals Physical DMG. As the controlled operator, Final Strike also deals 16 Stagger.\n DIVE ATTACK:\nBasic attack performed in mid-air becomes a dive attack that deals Physical DMG to nearby enemies.\n FINISHER:\nBasic attack performed near a Staggered enemy becomes a finisher attack that deals massive Physical DMG and recovers some SP.",
                "stats": [
                  {
                    "label": "BATK SEQ 1 Multiplier",
                    "value": "23%"
                  },
                  {
                    "label": "BATK SEQ 2 Multiplier",
                    "value": "28%"
                  },
                  {
                    "label": "BATK SEQ 3 Multiplier",
                    "value": "59%"
                  },
                  {
                    "label": "BATK SEQ 4 Multiplier",
                    "value": "81%"
                  },
                  {
                    "label": "BATK SEQ 5 Multiplier",
                    "value": "107%"
                  },
                  {
                    "label": "Finisher ATK Multiplier",
                    "value": "900%"
                  },
                  {
                    "label": "Dive ATK Multiplier",
                    "value": "180%"
                  }
                ]
              },
              {
                "name": "Tempestuous Arc",
                "type": "Combat Skill",
                "desc": "SKILL DESCRIPTION: Instantly blinks to the enemy's side to deal 2 slashes that deal some Physical DMG. If the enemy has active Electrification, Debuff Consumption the Electrification to unleash an additional attack that deals Electric DMG and recovers some SP.",
                "stats": [
                  {
                    "label": "SP Cost",
                    "value": "100"
                  },
                  {
                    "label": "SEQ 1 DMG Multiplier",
                    "value": "101%"
                  },
                  {
                    "label": "SEQ 2 DMG Multiplier",
                    "value": "101%"
                  },
                  {
                    "label": "SEQ 2 Stagger",
                    "value": "5"
                  },
                  {
                    "label": "Additional ATK DMG Multiplier",
                    "value": "405%"
                  },
                  {
                    "label": "Additional ATK Stagger",
                    "value": "5"
                  },
                  {
                    "label": "SP Recovery",
                    "value": "40"
                  }
                ]
              },
              {
                "name": "Peal of Thunder",
                "type": "Combat Skill",
                "desc": "COMBO TRIGGER: When an enemy suffers Electrification or after an enemy's Electrification is Debuff Consumption.\n SKILL DESCRIPTION: Blinks to the enemy's side to unleash a flurry of slashes that deals Physical DMG and recovers some SP.",
                "stats": [
                  {
                    "label": "Cooldown",
                    "value": "3"
                  },
                  {
                    "label": "DMG Multiplier",
                    "value": "350%"
                  },
                  {
                    "label": "SP Recovery",
                    "value": "10"
                  },
                  {
                    "label": "Stagger",
                    "value": "5"
                  },
                  {
                    "label": "Ultimate Energy Gain",
                    "value": "5"
                  }
                ]
              },
              {
                "name": "Exploding Blitz",
                "type": "Combat Skill",
                "desc": "SKILL DESCRIPTION: Performs a short forward dash while wreathed in arcs of electricity to deal Electric DMG and apply Electric Infliction to all enemies in the path. The lingering arcs explode after a short while, dealing another hit of Electric DMG. If the enemy has active Electric Infliction, Debuff Consumption the Electric Infliction and forcibly apply Electrification.",
                "stats": [
                  {
                    "label": "Ultimate Energy Cost",
                    "value": "90"
                  },
                  {
                    "label": "SEQ 1 DMG Multiplier",
                    "value": "350%"
                  },
                  {
                    "label": "SEQ 1 Stagger",
                    "value": "10"
                  },
                  {
                    "label": "SEQ 2 DMG Multiplier",
                    "value": "550%"
                  },
                  {
                    "label": "SEQ 2 Stagger",
                    "value": "10"
                  }
                ]
              }
            ]
          },
          {
            "title": "Talents",
            "entries": [
              {
                "name": "Blade of the Wildlands",
                "type": "Base Talent",
                "desc": "Assign to Manufacturing Cabin to grant weapon EXP material production efficiency +10/20% ."
              },
              {
                "name": "Hanna Traditions",
                "type": "Base Talent",
                "desc": "Assign to Reception Room to grant operators a small Clue 6/Clue 6 Rate-UP: Hannabit Circuit (activates upon assignment; effects of the same type cannot stack)"
              },
              {
                "name": "Wildland Trekker",
                "type": "Combat Talent",
                "desc": "Battle skill Tempestuous Arc improved: Triggering the additional effect 3 time(s) grants the team Electric DMG Dealt +0.05/0.08% for every point of Arclight's Intellect. This effect has a 15s duration and cannot stack."
              },
              {
                "name": "Hannabit Wisdom",
                "type": "Combat Talent",
                "desc": "30/50% chance to ignore an Arts Infliction applied on her."
              }
            ]
          },
          {
            "title": "Potentials",
            "entries": [
              {
                "name": "Child of the Storm",
                "type": "Potential 1",
                "desc": "Battle skill Tempestuous Arc improved: Triggering additional effects recovers another 10 SP."
              },
              {
                "name": "Speed Battler",
                "type": "Potential 2",
                "desc": "Agility +15 , Intellect +15 ."
              },
              {
                "name": "Hanna",
                "type": "Potential 3",
                "desc": "Talent Wildland Trekker improved: DMG Boost effect increased to 1.3 times the original."
              },
              {
                "name": "Aldertone's Teachings",
                "type": "Potential 4",
                "desc": "Ultimate Exploding Blitz improved: Ultimate Energy cost -15% ."
              },
              {
                "name": "Servant of the Wildlands",
                "type": "Potential 5",
                "desc": "Talent Wildland Trekker improved: Trigger requirement is reduced to 2 time(s)."
              }
            ]
          }
        ]
